export const notes=[
 "الأصل: «مأساة هاملت، أمير الدنمارك» لوليم شكسبير (نحو 1600)، من التراث العامّ. حافظنا على الفصول الخمسة وترتيب المشاهد، واختصرنا الحوار.",
 "من النصّ: كلّ بطاقةٍ عنوانها «من نصّ شكسبير» ترجمتُنا لسطرٍ من المسرحيّة، والأصل الإنجليزيّ تحتها، مع رقم الفصل والمشهد ومصدرين: مشروع غوتنبرغ (1524) ومكتبة فولجر لشكسبير.",
 "إرشادات المسرح بين قوسين، كما تُكتب في النصوص المسرحيّة: دخول الشخصيّات وخروجها، والمشاهد، والستارة.",
 "كما في المسرحيّة: الشبح على الأسوار، وزواج الملكة، ووصايا بولونيوس، وأمر الانتقام، والجنون المصطنع، و«كلمات كلمات كلمات»، والممثّلون ومقتل غونزاغو، و«أكون أو لا أكون» ومشهد الدير، وفرار الملك من المسرحيّة، والصلاة، وقتل بولونيوس خلف الستارة، والرسالة المبدَّلة والقراصنة، وأزهار أوفيليا وغرقها، وحفّار القبور وجمجمة يوريك، والمبارزة والسيف والكأس، وفورتنبراس.",
 "مختصر: روزنكرانتز وغيلدنسترن وأوزريك ورسل النرويج مذكورون في الإرشادات فقط، وحُذف بعض الحوار والمشاهد الصغيرة.",
 "ماذا لو؟ ثلاث نهايات ليست في المسرحيّة، تبدأ بإرشاد «هنا تخرج الحكاية عن مسرحيّة شكسبير»: الشكّ في الشبح والرجوع إلى فيتنبرغ، وضرب الملك وهو يصلّي، والصلح مع لايرتيس قبل المبارزة. وفي المشهد مع أوفيليا يمكن أن يلين هاملت لحظة، ثمّ تعود المسرحيّة إلى نصّها."
];
